package earth.terrarium.pastel.data.lang.guidebook.cuisine;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class ImperialCookbook {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.imperial_cookbook.page0.text", "  *Chef Aeverstrone of the\\\n     Scarlet Moon Court*");
		provider.add("book.pastel.guidebook.imperial_cookbook.page0.title", "To Feed a Kingdom");
		provider.add("book.pastel.guidebook.imperial_cookbook.page1.text", "Hello young one! I hope you've come to share in this little old man's love for cooking.\\\n\\\nTo introduce myself, I am Aeverstrone of Kurivinda, and I have served the [#](ff3d71)scarlet moon court[#]() for the last 80 years, serving as head imperial chef, though nowadays I mostly personally cook for the imperial family. Do forgive me if I digress a bit throughout this book, having been around for over 170 years gives you a lot to reminisce over!");
		provider.add("book.pastel.guidebook.imperial_cookbook.page10.text", "\\\nAh, wine, what a diverse and vibrant world. This recipe predates me - I know, it may surprise you to hear that there are things older than me, heh - it's a sort of desert wine, popular in my court and used in many recipes you may have seen.\\\n\\\nI'll tell you, go easy on it, this stuff hits a lot harder than you'd expect.");
		provider.add("book.pastel.guidebook.imperial_cookbook.page10.title", "A Pudding Wine");
		provider.add("book.pastel.guidebook.imperial_cookbook.page11.text", "*Reminiscent of mead, but closer to an alcoholic nectar.*");
		provider.add("book.pastel.guidebook.imperial_cookbook.page2.text", "\\\nEmperors and peaches, they are practically inseparable! Those nephrite trees that grow in these regions did not originate here, rather, they are endemic to a land far beyond this one, deep to the east. The love my Emperors have for glass peaches is so great that they've brought them everywhere they've gone - you could map out where they've reigned just by following the nephrite blossoms!");
		provider.add("book.pastel.guidebook.imperial_cookbook.page2.title", "Journey to the West");
		provider.add("book.pastel.guidebook.imperial_cookbook.page3.text", "*The Shura have gold, graceless humans have purple, but for us? The color of royalty is pink! Hahahah!*");
		provider.add("book.pastel.guidebook.imperial_cookbook.page4.text", "\\\nThis dish of lizard meat braised in wine and petals is a delicacy, and one that I would not blame you if you got it wrong the first 2 or 20 times you cooked it. To this day it remains one of the difficult dishes I cook regularly, it is a protracted process involving many delicate ingredients. But the result is something truly wonderful.");
		provider.add("book.pastel.guidebook.imperial_cookbook.page4.title", "A Luxurious Stew");
		provider.add("book.pastel.guidebook.imperial_cookbook.page5.text", "*Honestly, I never remember how to spell its name.*");
		provider.add("book.pastel.guidebook.imperial_cookbook.page6.text", "\\\nThe humble Junket, variants of this sweet, glutinous snack exist in all forms, though this one is a particularly eccentric one! I honestly do not enjoy preparing these very much, extracting the oils from the petals is a long and tedious process, but the children of the court always get so excited when they see the stuff - it makes my old heart swell.");
		provider.add("book.pastel.guidebook.imperial_cookbook.page6.title", "Fanciful Sweets");
		provider.add("book.pastel.guidebook.imperial_cookbook.page7.text", "*Imperator Aava loved this when he was a wee leveret.\\\n\\\nI'm pretty sure the goober still does.*");
		provider.add("book.pastel.guidebook.imperial_cookbook.page8.text", "\\\nI have a fun story tied to this recipe. Koi, in addition to being gorgeous creatures, make for the basis of some of the most unique and stunning imperial recipes. These recipes however often require odd and exotic ingredients, and one day we were clean out the night before a banquet. Thinking swiftly, I swapped out the ferment for [mother of moor](entry://general/fading), resulting in this flower-like dish.");
		provider.add("book.pastel.guidebook.imperial_cookbook.page8.title", "Lotus of the Sea");
		provider.add("book.pastel.guidebook.imperial_cookbook.page9.text", "*Don't let this ferment for too long or the mother is going to start eating away at the fish!*");
	}
}
